package com.wipro.hibernate;import org.hibernate.*;import java.math.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();String[][]d={{"MEENAKSHI","ENGINEER","50000"},{"RAHUL","DEVELOPER","45000"},{"PRIYA","TESTER","40000"},{"ARJUN","ANALYST","42000"},{"SNEHA","MANAGER","60000"}};for(String[]r:d){Employee e=new Employee();e.setName(r[0]);e.setDesignation(r[1]);e.setSalary(new BigDecimal(r[2]));s.persist(e);}t.commit();System.out.println("5 employee records inserted successfully.");}HibernateUtil.getSessionFactory().close();}}